"academyx": {
  "paramEyebrow": "Hegesztési Paraméterek",
  "paramTitle": "Tokos hegesztés: az irányértékek.",
  "paramLead": "Melegítési, átállítási és hűtési idők a DVS 2207-11 szerinti tokos hegesztéshez (fűtőelem 250-270 °C), ez az alapja a videókban bemutatott gyakorlatnak.",
  "paramHead": [
    "d (mm)",
    "Hegesztési mélység (mm)",
    "Melegítés (s)",
    "Átállítás max. (s)",
    "Hűtés (min)"
  ],
  "paramNote": "DVS 2207-11 szerinti irányértékek PP-hez 250-270 °C fűtőelem-hőmérsékleten. A hegesztőgép gyártójának adatai és a feldolgozási utasítás a kötelező érvényű. Kétség esetén: nézze meg a videót, ellenőrizze a paramétereket a gépen.",
  "stepEyebrow": "Eljárások Lépésről Lépésre",
  "stepTitle": "Négy eljárás, egy minőségi követelmény.",
  "stepLead": "Minden eljárásnak megvan a maga mérettartománya és öt lépése, amelyek meghatározzák a kapcsolat minőségét.",
  "procTabs": [
    "Tokos (Kézi)",
    "Tokos (Gép)",
    "Elektrofúziós",
    "Tompahegesztés"
  ],
  "procs": [
    {
      "t": "Kézi tokos hegesztés: d63-ig",
      "steps": [
        {
          "t": "Vágás és sorjázás",
          "d": "Vágja le a csövet derékszögben, tisztítsa meg és törje le az éleket. Használjon csővágót a K-Aqua szerszámprogramból."
        },
        {
          "t": "Hegesztési mélység jelölése",
          "d": "Jelölje be a csövön a táblázat szerinti betolási mélységet (pl. 14 mm d20 esetén): ez határozza meg az illesztési zónát."
        },
        {
          "t": "Egyidejű melegítés",
          "d": "A csövet a fűtőhüvelybe, az idomot a fűtőtüskére. Egyszerre tolja fel és tartsa be pontosan a melegítési időt."
        },
        {
          "t": "Gyors illesztés, forgatás nélkül",
          "d": "Az átállítási időn belül tengelyirányban csatlakoztassa. Soha ne forgassa el: a forgatás tönkreteszi a lágyított szerkezetet."
        },
        {
          "t": "Rögzítés és hűtés",
          "d": "Rögzítse a csatlakozást néhány másodpercig, majd várja meg a hűtési időt a mechanikai terhelés előtt."
        }
      ]
    },
    {
      "t": "Tokos hegesztés géppel: közepes méretek",
      "steps": [
        {
          "t": "Előkészítés, mint a kézi hegesztésnél",
          "d": "Vágás, sorjázás, hegesztési mélység jelölése. Az alapszabályok azonosak maradnak."
        },
        {
          "t": "Cső és idom befogása",
          "d": "A gép mindkét csatlakozó partnert koaxiálisan tartja. Az eltolódás és a dőlési hibák mechanikusan kizártak."
        },
        {
          "t": "Melegítés fűtőelemmel",
          "d": "Fűtőhüvely és -tüske a DVS irányértékei szerint; a gép reprodukálhatóan tartja a pozíciót és az időt."
        },
        {
          "t": "Gépi illesztés",
          "d": "Az előtolás tengelyirányban és egyenletesen csatlakozik, különösen d75 és d125 között ez az állandó minőség kulcsa."
        },
        {
          "t": "Hűtés rögzítés alatt",
          "d": "Csak a hűtési idő lejárta után lazítsa ki és folytassa a munkát."
        }
      ]
    },
    {
      "t": "Elektrofúziós hegesztés: Fűtőszálas idomok",
      "steps": [
        {
          "t": "Felület hámozása",
          "d": "Hámozza le és tisztítsa meg a csőfelületet a kötési zónában. Az oxidréteg és a szennyeződés megakadályozza a hegesztést."
        },
        {
          "t": "Betolási mélység jelölése",
          "d": "Jelölje be a mélységet a csövön, tolja a csövet ütközésig az idomba."
        },
        {
          "t": "Feszültségmentes rögzítés",
          "d": "Használjon rögzítőbilincseket: az idom hegesztés közben nem állhat hajlítófeszültség alatt."
        },
        {
          "t": "Hegesztési folyamat indítása",
          "d": "A készülék áram alá helyezi az idomba ágyazott fűtőszálakat. A paraméterek az idomból származnak, nem érzésből."
        },
        {
          "t": "Hűtési idő betartása",
          "d": "Csak a megadott hűtési idő után mozgassa vagy terhelje. Ellenőrizze a jelzőindikátorokat az idomon."
        }
      ]
    },
    {
      "t": "Tompahegesztés (Butt Fusion): Nagy méretek d630-ig",
      "steps": [
        {
          "t": "Végső síkgyalulás",
          "d": "Gyalulja síkra mindkét csővéget a gépben, amíg összefüggő forgács nem képződik: a párhuzamosság kötelező."
        },
        {
          "t": "Beállítás és eltolódás ellenőrzése",
          "d": "Az eltolódás legfeljebb a falvastagság 10%-a lehet. A d630-nál minden milliméter számít."
        },
        {
          "t": "Melegítés a fűtőelemen",
          "d": "Kiegyenlítés nyomás alatt a peremképződésig, majd nyomás nélküli áthevítés. Idők a DVS 2207-11 szerint."
        },
        {
          "t": "Átállítás és csatlakoztatás",
          "d": "Távolítsa el gyorsan a fűtőelemet, és mozgassa össze a végeket meghatározott csatlakozási nyomás alatt."
        },
        {
          "t": "Hűtés csatlakozási nyomás alatt",
          "d": "A csatlakozási nyomás a hűtési idő végéig fennmarad, ekkor jön létre a homogén, tartósan tömített szakasz."
        }
      ]
    }
  ],
